   118	
   119	export function displaySafeOpenAiSnapshotData<T>(data: T | null): T | null {
   120		if (!isStructuredObject(data) || !Array.isArray(data.actions)) return data;
   121		return {
   122			...data,
   123			actions: data.actions.filter(
   124				(action) =>
   125					!isStructuredObject(action) || action.tool !== "resolve_lobu_approval",
   126			),
   127		} as T;
   128	}
   129	
   130	/**
   131	 * Cache the latest server-authored view in ChatGPT's per-widget UI state. The
   132	 * snapshot is a display-only reload fallback; a fresh tool result always wins.
   133	 * Approval metadata stays excluded. The scoped snapshot capability is retained
   134	 * only as an opaque private correlation identity so delayed metadata cannot bind
   135	 * to another card merely because its display JSON happens to match.
   136	 */
   137	export function persistOpenAiViewSnapshot<T>(
   138		globals: unknown,
   139		data: T | null,
   140		resultIdentity: string | null = null,
   141	): boolean {
   142		if (!isStructuredObject(globals)) return false;
   143		const setWidgetState = globals.setWidgetState;
   144		if (typeof setWidgetState !== "function") return false;
   145	
   146		const widgetState = isStructuredObject(globals.widgetState)
   147			? globals.widgetState
   148			: {};
   149		const privateContent = isStructuredObject(widgetState.privateContent)
   150			? widgetState.privateContent
   151			: {};
   152		const nextWidgetState = {
   153			...widgetState,
   154			privateContent: {
   155				...privateContent,
   156				[LOBU_VIEW_SNAPSHOT_KEY]: {
   157					version: LOBU_VIEW_SNAPSHOT_VERSION,
   158					data: displaySafeOpenAiSnapshotData(data),
   159					...(resultIdentity ? { resultIdentity } : {}),
   160				},
   161			},
   162		};
   163	
   164		try {
   165			const result = Reflect.apply(setWidgetState, globals, [nextWidgetState]);
   166			if (isStructuredObject(result) && typeof result.catch === "function") {
   167				void Reflect.apply(result.catch, result, [() => {}]);
   168			}
   169			return true;
   170		} catch {
   171			return false;
   172		}
   173	}
   174	
   175	/**
   176	 * Read ChatGPT's compatibility globals without making them a dependency of the
   177	 * portable MCP Apps bridge. ChatGPT restores these globals for historical
   178	 * cards, including after the standard tool-result notification has already
   179	 * happened in an earlier page lifetime.
   180	 */
   181	export function readOpenAiCompatSnapshot<T>(
   182		globals: unknown,
   183	): OpenAiCompatSnapshot<T> {
   184		if (!isStructuredObject(globals)) {
   185			return {
   186				data: undefined,
   187				approvalCapability: undefined,
   188			};
   189		}
   190	
   191		const hasToolOutput = Object.hasOwn(globals, "toolOutput");
   192		const hasFullToolResult =
   193			hasToolOutput &&
   194			isStructuredObject(globals.toolOutput) &&
   195			Object.hasOwn(globals.toolOutput, "structuredContent");
   196		const widgetSnapshot = snapshotFromWidgetState<T>(globals.widgetState);
   197		const outputData = hasToolOutput
   198			? dataFromToolOutput<T>(globals.toolOutput)
   199			: widgetSnapshot.data;
   200		const hasToolResponseMetadata = Object.hasOwn(
   201			globals,
   202			"toolResponseMetadata",
   203		);
   204		const metadata = isStructuredObject(globals.toolResponseMetadata)
   205			? globals.toolResponseMetadata
   206			: null;
   207		const approvalCapability = hasToolResponseMetadata
   208			? metadata
   209				? (approvalCapabilityFromResult(metadata.mcp_tool_result) ??
   210					approvalCapabilityFromResult(metadata.call_tool_result))
   211				: null
   212			: hasFullToolResult
   213				? approvalCapabilityFromResult(globals.toolOutput)
   214				: undefined;
   215		const data =
   216			hasToolOutput && approvalCapability === null
   217				? displaySafeOpenAiSnapshotData(outputData)
   218				: outputData;
   219		const retainsWidgetIdentity =
   220			!hasToolOutput ||
   221			(isStructuredObject(outputData) && Object.keys(outputData).length === 0);
   222	
   223		return {
   224			data,
   225			...(retainsWidgetIdentity && widgetSnapshot.resultIdentity !== undefined
   226				? { resultIdentity: widgetSnapshot.resultIdentity }
   227				: {}),
   228			approvalCapability,
   229		};
   230	}
