     9	
    10	/**
    11	 * The single MCP App bundle. It renders whatever `{title, blocks, actions}`
    12	 * view the host streams and routes each action through the standard MCP Apps
    13	 * bridge (`tools/call` or `ui/open-link`) — every interactive interaction is
    14	 * just a different view through this one bundle.
    15	 * All MCP-transport plumbing lives in `../_shared/host`.
    16	 */
    17	
    18	/** Sample view shown when opened standalone (dev/test, not embedded). */
    19	const DEV_MOCK: InteractionView = {
    20		version: 1,
    21		title: "Update agent support-triage",
    22		tone: "warning",
    23		blocks: [
    24			{
    25				type: "diff",
    26				fields: [
    27					{
    28						label: "description",
    29						before: "Answers support questions on request",
    30						after: "Triages #support and drafts replies every morning",
    31					},
    32				],
    33			},
    34		],
    35		actions: [
    36			{
    37				id: "review",
    38				label: "Review in Lobu",
    39				variant: "primary",
    40				icon: "external",
    41				terminal: false,
    42				href: "https://lobu.ai/example/runs/42",
    43			},
    44		],
    45	};
    46	
    47	function InteractionApp() {
    48		const {
    49			data,
    50			resultUnavailable,
    51			toolName,
    52			viewState,
    53			setViewState,
    54			callTool,
    55			openLink,
    56			lastResult,
    57			allowSpaHostedViews,
    58		} = useMcpApp<unknown>();
    59		const [pendingId, setPendingId] = useState<string | null>(null);
    60	
    61		// Host brokered the `tools/call`; the returned structured result replaces
    62		// the card on success, while errors simply re-enable the original action.
    63		useEffect(() => {
    64			if (!lastResult) return;
    65			setPendingId(null);
    66		}, [lastResult]);
    67	
    68		if (resultUnavailable) {
    69			return (
    70				<div className="p-2 text-xs text-muted-foreground">
    71					This result is no longer available.
    72				</div>
    73			);
    74		}
    75	
    76		if (!data) {
    77			return <div className="p-2 text-xs text-muted-foreground">Loading…</div>;
    78		}
    79	
    80		const onAction = (action: InteractionAction) => {
    81			if (action.href) {
    82				void openLink(action.href);
    83				return;
    84			}
    85			if (!action.tool) return;
    86			if (action.terminal !== false) setPendingId(action.id);
    87			void callTool(action.tool, action.args ?? {});
    88		};
    89	
    90		return (
    91			<McpResultView
    92				value={data}
    93				toolName={toolName ?? undefined}
    94				viewState={viewState}
    95				onViewStateChange={setViewState}
    96				onAction={onAction}
    97				openLink={(href) => void openLink(href)}
    98				pendingId={pendingId}
    99				allowSpaHostedViews={allowSpaHostedViews}
   100			/>
   101		);
   102	}
   103	
   104	mountMcpApp({ devMock: DEV_MOCK, App: InteractionApp });
